import{_ as t,o as i,c as o,a2 as r}from"./chunks/framework.BXzK3EA4.js";const h=JSON.parse('{"title":"Git 版本控制","description":"Git 是现代软件工程的基础设施。本目录涵盖 Git 的核心概念和常见工作流。","frontmatter":{},"headers":[],"relativePath":"工具/git/index.md","filePath":"工具/git/index.md","lastUpdated":1793930980000}'),a={name:"工具/git/index.md"};function l(c,e,d,n,s,_){return i(),o("div",null,[...e[0]||(e[0]=[r('<h1 id="git-版本控制" tabindex="-1">Git 版本控制 <a class="header-anchor" href="#git-版本控制" aria-label="Permalink to &quot;Git 版本控制&quot;">​</a></h1><blockquote><p>Git 是现代软件工程的基础设施。本目录涵盖 Git 的核心概念和常见工作流。</p></blockquote><h2 id="📚-章节列表" tabindex="-1">📚 章节列表 <a class="header-anchor" href="#📚-章节列表" aria-label="Permalink to &quot;📚 章节列表&quot;">​</a></h2><ol><li><a href="./1-HEAD_tree_index">HEAD_tree_index.md</a> — HEAD / tree / index 三大核心概念详解</li><li><a href="./2-Version-control">Version control.md</a> — 版本控制基本原理</li><li><a href="./3-fork_clone_branch">fork_clone_branch.md</a> — fork / clone / branch 工作流</li><li><a href="./4-git_pull_fetch">git_pull_fetch.md</a> — 远程同步详解</li><li><a href="./5-git_rebase_merge">git_rebase_merge.md</a> — 合并策略</li><li><a href="./6-git_reset_revert">git_reset_revert.md</a> — 两种撤销方式</li><li><a href="./7-git_stash">git stash.md</a> — 临时保存工作进度</li><li><a href="./8-git-config">git-config.md</a> — Git 配置 user.name / user.email（项目本地 + 全局）</li></ol><h2 id="📝-小结" tabindex="-1">📝 小结 <a class="header-anchor" href="#📝-小结" aria-label="Permalink to &quot;📝 小结&quot;">​</a></h2><ul><li>8 章按「<strong>版本控制概念 → 三大对象 → 日常命令 → 高阶操作</strong>」组织,既是知识梳理也是面试题库。</li><li>核心主线是 Git 的<strong>三棵树模型</strong>(HEAD / index / working tree)与<strong>引用模型</strong>(commit / branch / tag / reflog),理解这两张图所有命令都能推出来。</li><li>高频对比题:<code>pull</code> vs <code>fetch</code>、<code>merge</code> vs <code>rebase</code>、<code>reset</code> vs <code>revert</code>、<code>fork</code> vs <code>clone</code>。</li><li>事故恢复三件套:<code>git reflog</code>(找回丢失提交)、<code>git bisect</code>(二分定位 bug)、<code>git stash</code>(临时收起改动)。</li><li>面试怎么讲:别只背命令,要能说「<strong>这个命令动了哪棵树/哪个引用</strong>」。</li></ul>',6)])])}const f=t(a,[["render",l]]);export{h as __pageData,f as default};
